rules:
@keyframes codex-dream-skin-media-pulse { 
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.008); }
}

@keyframes codex-dream-skin-overlay-pulse { 
  0%, 100% { opacity: calc(var(--dream-state-overlay-opacity, 0) * .68); }
  50% { opacity: var(--dream-state-overlay-opacity, 0); }
}

@keyframes codex-dream-skin-media-flash { 
  0% { opacity: calc(var(--dream-state-media-opacity, .78) * .86); }
  45% { opacity: 1; }
  100% { opacity: var(--dream-state-media-opacity, .78); }
}

@keyframes codex-dream-skin-overlay-flash { 
  0% { opacity: 0; }
  45% { opacity: var(--dream-state-overlay-opacity, 0); }
  100% { opacity: calc(var(--dream-state-overlay-opacity, 0) * .72); }
}

@keyframes codex-dream-skin-media-alert { 
  0%, 100% { opacity: var(--dream-state-media-opacity, .88); }
  35% { opacity: 1; }
  70% { opacity: calc(var(--dream-state-media-opacity, .88) * .82); }
}

@keyframes codex-dream-skin-overlay-alert { 
  0%, 100% { opacity: var(--dream-state-overlay-opacity, 0); }
  35% { opacity: min(calc(var(--dream-state-overlay-opacity, 0) * 1.4), .35); }
  70% { opacity: calc(var(--dream-state-overlay-opacity, 0) * .58); }
}

html[data-dream-skin="active"] aside:is(.app-shell-left-panel, [class~="bg-token-main-surface-primary"]) { background: linear-gradient(180deg,
      rgb(var(--ds-panel-rgb) / .98),
      rgb(var(--ds-bg-rgb) / .96)) !important; border-left: 0px !important; border-radius: 0px 16px 16px 0px !important; box-shadow: 10px 0 30px rgb(var(--ds-bg-rgb) / .22) !important; color: var(--ds-text) !important; backdrop-filter: none !important; }

html[data-dream-skin="active"] aside[class~="bg-token-main-surface-primary"] { background: linear-gradient(90deg,
    rgb(var(--ds-panel-rgb) / .46),
    rgb(var(--ds-bg-rgb) / .58) 100%) !important; border: 0px !important; border-radius: 0px !important; box-shadow: none !important; color: var(--ds-text) !important; backdrop-filter: blur(8px) saturate(106%) !important; }

html[data-dream-skin="active"]:is([data-dream-task-mode="full"], [data-dream-art-task-mode="full"])[data-dream-art-wide="true"]:has(main:is(.main-surface, [data-app-shell-main-surface], [class*="_MainContentSurface_"])):not(:has(main:is(.main-surface, [data-app-shell-main-surface], [class*="_MainContentSurface_"]) [role="main"])) aside:is(.app-shell-left-panel, [class~="bg-token-main-surface-primary"]) { background: linear-gradient(90deg,
    var(--ds-immersive-sidebar),
    var(--ds-immersive-edge) 100%) !important; border: 0px !important; border-radius: 0px !important; box-shadow: none !important; backdrop-filter: none !important; }

html[data-dream-skin="active"]:is([data-dream-task-mode="ambient"], [data-dream-art-task-mode="ambient"], [data-dream-task-mode="banner"], [data-dream-art-task-mode="banner"])[data-dream-art-wide="true"]:has(main:is(.main-surface, [data-app-shell-main-surface], [class*="_MainContentSurface_"])):not(:has(main:is(.main-surface, [data-app-shell-main-surface], [class*="_MainContentSurface_"]) [role="main"])) aside:is(.app-shell-left-panel, [class~="bg-token-main-surface-primary"]) { background: linear-gradient(90deg,
    rgb(var(--ds-panel-rgb) / .46),
    rgb(var(--ds-bg-rgb) / .58) 100%) !important; border: 0px !important; border-radius: 0px !important; box-shadow: none !important; backdrop-filter: none !important; }

html[data-dream-skin="active"]:not(:has(main:is(.main-surface, [data-app-shell-main-surface], [class*="_MainContentSurface_"]))) [data-ds-part="sidebar"] { background: linear-gradient(180deg,
      rgb(var(--ds-panel-rgb) / .98),
      rgb(var(--ds-bg-rgb) / .96)) !important; border: 1px solid var(--ds-line) !important; color: var(--ds-text) !important; box-shadow: 10px 0 30px rgb(var(--ds-bg-rgb) / .22) !important; backdrop-filter: none !important; }

html[data-dream-skin="active"][data-dream-art-wide="true"]:not(:has(main:is(.main-surface, [data-app-shell-main-surface], [class*="_MainContentSurface_"]))) [data-ds-part="sidebar"] { background: linear-gradient(90deg,
    var(--ds-immersive-sidebar),
    var(--ds-immersive-edge) 100%) !important; border: 0px !important; box-shadow: none !important; }

html[data-dream-skin="active"][data-dream-art-wide="true"]:has(main:is(.main-surface, [data-app-shell-main-surface], [class*="_MainContentSurface_"]) [role="main"]) aside:is(.app-shell-left-panel, [class~="bg-token-main-surface-primary"]) { background: linear-gradient(90deg,
    var(--ds-immersive-sidebar),
    var(--ds-immersive-edge) 100%) !important; border: 0px !important; border-radius: 0px !important; box-shadow: none !important; backdrop-filter: none !important; }

html[data-dream-skin="active"][data-dream-art-wide="true"] .composer-surface-chrome { background: rgb(var(--ds-panel-rgb) / var(--ds-window-opacity-composer-shell)) !important; border: 0px !important; box-shadow: 0 10px 30px rgb(var(--ds-bg-rgb) / .20),
    inset 0 0 0 1px var(--ds-immersive-line),
    inset 0 1px rgb(var(--ds-text-rgb) / .12) !important; backdrop-filter: none !important; }

html[data-dream-skin="active"][data-dream-shell="light"][data-dream-art-wide="true"] .composer-surface-chrome { box-shadow: 0 10px 28px rgb(var(--ds-bg-rgb) / .14),
    inset 0 0 0 1px var(--ds-immersive-line),
    inset 0 1px rgb(var(--ds-panel-rgb) / .72) !important; backdrop-filter: blur(8px) saturate(102%) !important; }

html[data-dream-skin="active"] [class*="_homeUtilityBar_"] { top: 0px !important; width: 100% !important; margin-inline: 0px !important; padding-inline: 18px !important; border-radius: 22px 22px 0px 0px !important; background: rgb(var(--ds-panel-rgb) / .56) !important; box-shadow: inset 1px 0 rgb(var(--ds-muted-rgb) / .18),
    inset -1px 0 rgb(var(--ds-muted-rgb) / .18),
    inset 0 1px rgb(var(--ds-muted-rgb) / .18) !important; backdrop-filter: blur(16px) saturate(108%) !important; }

html[data-dream-skin="active"][data-dream-art-wide="true"] [class*="_homeUtilityBar_"] { background: var(--ds-immersive-composer-solid) !important; box-shadow: inset 1px 0 var(--ds-immersive-line),
    inset -1px 0 var(--ds-immersive-line),
    inset 0 1px rgb(var(--ds-text-rgb) / .12) !important; backdrop-filter: none !important; }

html[data-dream-skin="active"][data-dream-shell="light"][data-dream-art-wide="true"] [class*="_homeUtilityBar_"] { box-shadow: inset 1px 0 var(--ds-immersive-line),
    inset -1px 0 var(--ds-immersive-line),
    inset 0 1px rgb(var(--ds-panel-rgb) / .72) !important; backdrop-filter: blur(8px) saturate(102%) !important; }

@media (max-width: 1120px) {
  html[data-dream-skin="active"] main:is(.main-surface, [data-app-shell-main-surface], [class*="_MainContentSurface_"]):has([role="main"])::after { content: none; }
  html[data-dream-skin="active"] [role="main"]:has([data-testid="home-icon"]) { --thread-content-max-width: min(940px, calc(100cqw - 30px)) !important; }
  html[data-dream-skin="active"] [role="main"]:has([data-testid="home-icon"]) > div:first-child > div:first-child > div:first-child { width: calc(100% - 28px) !important; }
}

@media (max-width: 900px) {
  html[data-dream-skin="active"] [role="main"]:has([data-testid="home-icon"]) > div:first-child > div:first-child { flex-basis: 408px !important; min-height: 408px !important; }
  html[data-dream-skin="active"] [role="main"]:has([data-testid="home-icon"]) > div:first-child > div:first-child > div:first-child { height: 232px !important; min-height: 232px !important; }
  html[data-dream-skin="active"] [role="main"]:has([data-testid="home-icon"]) > div:first-child > div:first-child > div:first-child > div:first-child { padding: 0px 26px; }
  html[data-dream-skin="active"] [role="main"]:has([data-testid="home-icon"]) > div:first-child > div:first-child > div:first-child > div:first-child > div:first-child { width: min(58%, 460px) !important; }
  html[data-dream-skin="active"] [role="main"]:has([data-testid="home-icon"]) [data-feature="game-source"] { font-size: 18px !important; }
  html[data-dream-skin="active"] [role="main"]:has([data-testid="home-icon"]) [data-feature="game-source"]::before { margin-bottom: 7px; font-size: 10px; }
  html[data-dream-skin="active"] [role="main"]:has([data-testid="home-icon"]) [data-feature="game-source"]::after { margin-top: 9px; font-size: 11px; }
  html[data-dream-skin="active"] [role="main"]:has([data-testid="home-icon"]) .group\/home-suggestions button { min-height: 112px !important; font-size: 12px !important; }
}

@layer dreamskin-accessibility {
  @media (prefers-reduced-motion: reduce) {
  html[data-dream-skin="active"] *, html[data-dream-skin="active"] ::before, html[data-dream-skin="active"] ::after { scroll-behavior: auto !important; transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; }
}
}

@layer dreamskin-community {
  [data-ds-part="root"] { color: var(--ds-theme-color-text) !important; }
  [data-ds-part="root"] body { color: var(--ds-theme-color-text) !important; }
}
